*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF40003.xml";
scwin.vSecugrpID = "";
scwin.list_dtl_noti_id;
scwin.belongDepCd = js_belngdepcd;
scwin.selBzProcsNo, scwin.selPrtDepoId, scwin.selExerSeq, scwin.selRowPos, scwin.isGongsi = "";
scwin.vIsurCd, scwin.vComNm = "";
scwin.clickBzProcsNo, scwin.clickListProcsStatCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    if (txb_ISUR_CD.getValue() == "") {
        $c.win.alert("[회사]를 선택해주세요.");
        txb_ISUR_CD.focus();
        return;
    }
    var ISUR_CD = txb_ISUR_CD.getValue();
    var url = "/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listStockOptionDutyHold&inputMessageId=STOCKOPTION_DUTYHOLD_LIST_INOUT";
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&LD_MKT_TP_CD=" + js_market;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


//2010.04.20 회사코드 추가
scwin.fn_SetPar = function(arrPar) {
    txb_COM_NM.setValue(arrPar[0].COM_NM);
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
};
scwin.checkCount = function() {
    var count = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        checked.setValue(dts_List.getCellData(i, "CHK_YN"));
        if (checked == "T") count++;
    }
    return count;
};
scwin.checkOnly = function(selRow, bCheck) {
    var checked = "";
    if (bCheck == 1) {
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            checked.setValue(dts_List.getCellData(i, "CHK_YN"));
            if (selRow == i) continue;
            dts_List.setCellData(i, "CHK_YN", "");
        }
    }
};
scwin.checkChecked = function() {
    var rowPos = 0;
    rowPos = $c.cp.getNameValueRow(dts_List, "CHK_YN", "T");
    if (rowPos == 0) {
        $c.win.alert("선택된 항목이 없습니다.");
    }
    return rowPos;
};
scwin.checkProcsStatCd = function() {
    var listProcsStatCd = "";
    var check = "";
    var isPass = true;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        listProcsStatCd = dts_List.getCellData(i, "LIST_PROCS_STAT_CD");
        check = dts_List.getCellData(i, "CHK_YN");
        if (check == "T" && listProcsStatCd != "32") {
            $c.win.alert("처리상태가 제출완료인 항목만 처리가능합니다.");
            return false;
        }
    }
    return isPass;
    송;
};
scwin.checkValid = function(selRow, bCheck) {
    var checked = "";
    if (bCheck == 1) {
        var stkoptDutyExerSeq = dts_List.getCellData(selRow, "STKOPT_DUTY_EXER_SEQ");
        //2600 유가공시부, 3400 코스닥공시부
        if (scwin.belongDepCd == "2600" || scwin.belongDepCd == "3400") {
            if (stkoptDutyExerSeq == "99999") {
                $c.win.alert("대상자는 상장부에서만 선택할수 있습니다");
                dts_List.setCellData(selRow, "CHK_YN", "");
            }
            //2500 유가상장부, 3300 코스닥 상장부

        } else if (scwin.belongDepCd == "2500" || scwin.belongDepCd == "3300") {
            if (stkoptDutyExerSeq != "99999") {
                $c.win.alert("납입일은 공시부에서만 선택할수 있습니다.");
                dts_List.setCellData(selRow, "CHK_YN", "");
            }
        }
    }
};
scwin.checkIsurCd = function() {
    var isurCd = $c.stf.getObjectValue(txb_ISUR_CD);
    if (isurCd.length > 0) {
        return true;
    } else {
        return false;
    }
};
scwin.fn_setBzProcsNo = function(obj) {
    scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.clickListProcsStatCd = dts_List.getCellData(eval(obj), "LIST_PROCS_STAT_CD");
    var stkoptDutyExerSeq = dts_List.getCellData(eval(obj), "STKOPT_DUTY_EXER_SEQ");
    if (stkoptDutyExerSeq != "99999") {
        scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "FOLLW_BZ_PROCS_NO");
    }
};
scwin.fn_Receive = function(type) {
    var typeString = "";
    if (type == "33") typeString = "접수";

    else typeString = "반려";
    if (scwin.checkChecked() > 0) {
        if (scwin.checkProcsStatCd()) {
            var vAnswer = confirm("선택된 항목을 모두 " + typeString + "처리 하시겠습니까?");
            if (vAnswer) {
                vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
                trs_Save.Action = $c.lc.fn_encodeNSession("/StockOptionDutyHold.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=processStkOpt");
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
                trs_Save.Parameters = "TRS_IDX=U" + ", LIST_BZ_TP_CD=770" + ", LIST_PROCS_STAT_CD=" + type + ",PROCS_EMP_NO=" + js_emp_no;
                trs_Save.Post();
            }
        }
    }
};
scwin.btn_select_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_Grid, "주식매수선택권 의무보유", "", 1, 0);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //txb_TotCnt.value = "총 " + rowcount + "건";						 
    if (rowcount <= 0) {
        dts_List.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    if (colid == "CHK_YN") return;
    var stkoptDutyExerSeq = dts_List.getCellData(row, "STKOPT_DUTY_EXER_SEQ");
    var type = "";
    //공시부
    if (scwin.belongDepCd == "2600" || scwin.belongDepCd == "3400") {
        if (stkoptDutyExerSeq == "99999") {
            return;
        }
        //2500 유가상장부, 3300 코스닥 상장부

    } else if (scwin.belongDepCd == "2500" || scwin.belongDepCd == "3300") {
        if (stkoptDutyExerSeq != "99999") {
            return;
        }
    }
    if (row > 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    }
    if ("34" == scwin.clickListProcsStatCd) {
        //수정요청 리스트 팝업창
        var adjreqUrl = "/lstmgt/ULDSTF40005.gfm";
        await $c.frame.CreateDialogFrame("ULDSTF07090.gfm", adjreqUrl, "주식매수선택권 의무보유 수정요청 리스트", 50, 50, 940, 300, "window");
    }
    //2500 유가상장부, 3300 코스닥 상장부
    if (scwin.belongDepCd == "2500" || scwin.belongDepCd == "3300" || js_dep_cd == 'ZSYS') {
        scwin.isGongsi = false;
        scwin.selBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
        scwin.selPrtDepoId = dts_List.getCellData(row, "PRTDEPO_ID");
        scwin.selExerSeq = dts_List.getCellData(row, "STKOPT_DUTY_EXER_SEQ");
        await $c.frame.CreateDialogFrame("ULDSTF40004", "/lstmgt/ULDSTF40004.gfm", "주식매수선택권 의무보유 관리 상세내역", 200, 200, 790, 400, "window");
    }
};
scwin.btn_Input_onclick = async function() {
    scwin.selBzProcsNo = "";
    scwin.selPrtDepoId = "";
    scwin.selExerSeq = "";
    await $c.frame.CreateDialogFrame("ULDSTF40004", "/lstmgt/ULDSTF40004.gfm", "주식매수선택권 의무보유 관리 상세내역 등록", 200, 200, 790, 350, "window");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(__GROUPBOX_BACKGROUND__panel_1);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    $c.stf.showObj(btn_Input, false);
    //2600 유가공시부, 3400 코스닥공시부
    if (scwin.belongDepCd == "2600" || scwin.belongDepCd == "3400") {
        $c.stf.showObj(btn_Modify, false);
        //2500 유가상장부, 3300 코스닥 상장부

    } else if (scwin.belongDepCd == "2500" || scwin.belongDepCd == "3300") {
        $c.stf.showObj(btn_Modify, false);
    } else {
        //showObj(btn_Input, false);
        $c.stf.showObj(btn_Modify, false);
        $c.cm.setColumnProp(grd_Grid, "CHK_YN", "edit", "none");
    }
    if (js_dep_cd == 'ZSYS') {
        $c.stf.showObj(btn_Input, true);
        $c.stf.showObj(btn_Modify, true);
        $c.cm.setColumnProp(grd_Grid, "CHK_YN", "edit", "any");
    }
    scwin.vIsurCd = $c.frame.path("../").vStkOptIsurCd;
    scwin.vComNm = $c.frame.path("../").vStkOptComNm;
    //신주추가상장에서 호출
    if (scwin.vIsurCd != null && scwin.vIsurCd.length > 0) {
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.vIsurCd);
        $c.stf.setObjectValue(txb_COM_NM, scwin.vComNm);
        txb_ISUR_CD.setReadOnly(true);
        txb_ISUR_CD.setDisabled(true);
        txb_ISUR_CD.style.backgroundColor = "#b9d4f7";
        $c.stf.showObj(img_COM_NM, false);
        scwin.fn_list_sync();
    }
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_COM_NM_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Modify_onclick = async function() {
    var rowPos = scwin.checkChecked();
    if (rowPos > 0) {
        if (scwin.checkCount() > 1) {
            $c.win.alert("하나만 수정할 수 있습니다.");
        } else {
            var payDd = dts_List.getCellData(rowPos, "STKOPT_DUTY_EXER_PAY_DD");
            if (js_dep_cd != 'ZSYS' && payDd.length == 0) {
                $c.win.alert("수정할 납입일 정보가 없습니다");
                return;
            }
            var res = window.confirm("선택된 항목의 납입일, 행사주식수만 수정됩니다.\n진행하시겠습니까?");
            if (res) {
                scwin.isGongsi = true;
                scwin.selBzProcsNo = dts_List.getCellData(rowPos, "BZ_PROCS_NO");
                scwin.selPrtDepoId = dts_List.getCellData(rowPos, "PRTDEPO_ID");
                scwin.selExerSeq = dts_List.getCellData(rowPos, "STKOPT_DUTY_EXER_SEQ");
                await $c.frame.CreateDialogFrame("ULDSTF40004", "/lstmgt/ULDSTF40004.gfm", "주식매수선택권 의무보유 관리 상세내역", 200, 200, 790, 400, "window");
            }
        }
    }
};
scwin.grd_Grid_OnCheckClick = function(col, colid, bCheck) {
    //checkOnly(col, bCheck);
    scwin.checkValid(col, bCheck);
};
scwin.btn_Acpt_onclick = function() {
    scwin.fn_Receive("33");
};
scwin.btn_Ret_onclick = function() {
    scwin.fn_Receive("37");
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
};
